    ["Everything together is too long. Shorten something so it stays under {max} characters."] = "Tudo junto está muito longo. Encurte algo para ficar abaixo de {max} caracteres.",
    ["Example lines"] = "Exemplos de fala",
    ["Facts the character noticed while you talked. Change or delete the ones that are wrong."] = "Fatos que o personagem percebeu nas conversas. Altere ou exclua os que estiverem errados.",
    ["For example: V has a sister called Lena."] = "Por exemplo: V tem uma irmã chamada Lena.",
    ["Go back to the shipped text for {name}? All your changes to this character are removed."] = "Voltar ao texto original de {name}? Todas as suas mudanças neste personagem serão removidas.",
    ["Go back to the shipped text for {name}? Your changes to this part are removed."] = "Voltar ao texto original de {name}? As suas mudanças nesta parte serão removidas.",
    ["How they sound: pace, attitude, favourite habits of speech."] = "Como eles soam: ritmo, atitude e manias de fala favoritas.",
    ["Lines in their voice. They show the tone only and are never said back word for word."] = "Falas na voz deles. Elas mostram apenas o tom e nunca são repetidas palavra por palavra.",
